const lenis = new Lenis({
	lerp: 0.08,
});
function raf(time) {
  lenis.raf(time);
  requestAnimationFrame(raf);
}
requestAnimationFrame(raf);

window.Webflow ||= [];

window.Webflow.push(() => {

  gsap.registerPlugin(ScrollTrigger);

  const style = document.createElement("style");

  style.textContent = `
    .train-counter {
      display: inline-flex;
      align-items: flex-start;
      white-space: nowrap;
    }

    .digit-window {
      position: relative;
      display: inline-block;
      width: 0.62em;
      height: 1em;
      overflow: hidden;
      vertical-align: top;
    }

    .digit-train {
      display: block;
      will-change: transform;
    }

    .digit {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 0.62em;
      height: 1em;
      line-height: 1;
    }

    .static-char {
      display: inline-block;
      height: 1em;
      line-height: 1em;
    }

    .static-char.dot {
      width: 0.25em;
    }
  `;

  document.head.appendChild(style);

  function createTrainCounter(counter) {

    const originalText = counter.textContent.trim();

    counter.innerHTML = "";

    let digitPosition = 0;

    const trains = [];

    [...originalText].forEach((char) => {

      if (/^\d$/.test(char)) {

        const targetDigit = Number(char);

        const digitWindow =
          document.createElement("span");

        digitWindow.className =
          "digit-window";

        const digitTrain =
          document.createElement("span");

        digitTrain.className =
          "digit-train";

        for (let cycle = 0; cycle < 4; cycle++) {

          for (let number = 0; number <= 9; number++) {

            const digit =
              document.createElement("span");

            digit.className = "digit";

            digit.textContent = number;

            digitTrain.appendChild(digit);

          }

        }

        digitWindow.appendChild(digitTrain);

        counter.appendChild(digitWindow);

        const direction =
          digitPosition % 2 === 0
            ? "up"
            : "down";


        trains.push({
          train: digitTrain,
          window: digitWindow,
          targetDigit,
          direction
        });


        digitPosition++;

      }

      else {

        const staticChar =
          document.createElement("span");

        staticChar.className =
          "static-char";


        if (char === ".") {
          staticChar.classList.add("dot");
        }


        staticChar.textContent = char;

        counter.appendChild(staticChar);

      }

    });

    requestAnimationFrame(() => {

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: counter,
          start: "top 80%",
          once: true
        }
      });

      trains.forEach((item) => {

        const digitHeight =
          item.window.offsetHeight;

        const finalIndex =
          item.targetDigit + 20;

        if (item.direction === "up") {

          const startIndex =
            item.targetDigit + 10;


          gsap.set(item.train, {
            y: -(startIndex * digitHeight)
          });


          tl.to(
            item.train,
            {
              y: -(finalIndex * digitHeight),
              duration: 2.5,
              ease: "power3.out"
            },
            0
          );

        }

        else {

          const startIndex =
            item.targetDigit + 30;


          gsap.set(item.train, {
            y: -(startIndex * digitHeight)
          });


          tl.to(
            item.train,
            {
              y: -(finalIndex * digitHeight),
              duration: 2.5,
              ease: "power3.out"
            },
            0
          );

        }

      });

      ScrollTrigger.refresh();

    });

  }

  document
    .querySelectorAll(".train-counter")
    .forEach(createTrainCounter);


});

window.Webflow ||= [];
window.Webflow.push(() => {
  const cardWraps = document.querySelectorAll(".card-hero-wrap");

  cardWraps.forEach((cardWrap) => {
    const counterEl = cardWrap.querySelector(".conter-namber");
    const cardWrapper = cardWrap.querySelector(".hero-card-wrapper");
    const cards = cardWrap.querySelectorAll(".hero-card-box");

    if (!counterEl || !cardWrapper || cards.length < 2) return;

    // 1. Wrapper ebong Counter-er proyojoniyo style GSAP diye set kora
    gsap.set(cardWrap, { overflow: "hidden" });

    gsap.set(cardWrapper, {
      display: "flex",
      flexWrap: "nowrap",
      willChange: "transform"
    });

    gsap.set(counterEl, {
      display: "inline-flex",
      alignItems: "flex-start",
      overflow: "hidden",
      height: "1.15em",
      lineHeight: "1.15em",
      position: "relative",
      webkitMaskImage: "linear-gradient(to bottom, transparent 0%, black 15%, black 85%, transparent 100%)",
      maskImage: "linear-gradient(to bottom, transparent 0%, black 15%, black 85%, transparent 100%)"
    });

    // 2. Protita digit-er train sequence (13,1470 -> 23,1470)
    const digitTracks = [
      ["1", "2"],
      ["3", "0", "1", "2", "3"],
      [","],
      ["1", "0", "1"],
      ["4", "0", "1", "2", "3", "4"],
      ["7", "0", "1", "2", "3", "4", "5", "6", "7"],
      ["0"]
    ];

    counterEl.innerHTML = "";
    const rollingCols = [];

    digitTracks.forEach((track, index) => {
      const col = document.createElement("span");

      gsap.set(col, {
        display: "inline-flex",
        flexDirection: "column",
        willChange: "transform"
      });

      track.forEach((char) => {
        const item = document.createElement("span");
        item.textContent = char;
        gsap.set(item, {
          height: "1.15em",
          lineHeight: "1.15em",
          display: "flex",
          alignItems: "center",
          justifyContent: "center"
        });
        col.appendChild(item);
      });

      if (index === digitTracks.length - 1) {
        gsap.set(col, { opacity: 0.35 });
      }

      if (track.length > 1) {
        rollingCols.push(col);
      }

      counterEl.appendChild(col);
    });

    // 3. 2nd card-er slide distance ber kora
    const getSlideDistance = () => {
      return -(cards[1].offsetLeft - cards[0].offsetLeft);
    };

    // 4. Main GSAP Timeline
    const tl = gsap.timeline({
      repeat: -1,
      yoyo: true,
      delay: 2,
      repeatDelay: 2,
      defaults: {
        duration: 1.2,
        ease: "expo.inOut"
      }
    });

    tl.to(cardWrapper, {
      x: () => getSlideDistance()
    }, "syncAnim")
    .to(rollingCols, {
      yPercent: (i, el) => {
        const totalItems = el.children.length;
        return -((totalItems - 1) / totalItems) * 100;
      },
      stagger: 0.03
    }, "syncAnim");
  });
});

window.Webflow ||= [];

window.Webflow.push(() => {
  if (!window.gsap) return;

  const items = document.querySelectorAll(
    ".financial-benefits-card-faq-box .financial-benefits-faq"
  );

  const activeClass = "financial-benefits-faq-active";

  items.forEach((item) => {
    const content = item.querySelector(".faq-toggle-content");
    const icon = item.querySelector(".faq-item-icon");

    if (!content || !icon) return;

    gsap.set(content, {
      height: item.classList.contains(activeClass) ? "auto" : 0,
      overflow: "hidden"
    });

    gsap.set(icon, {
      rotation: item.classList.contains(activeClass) ? 135 : 0
    });

    item.style.cursor = "pointer";

    item.addEventListener("click", () => {
      const isActive = item.classList.contains(activeClass);

      items.forEach((otherItem) => {
        const otherContent = otherItem.querySelector(".faq-toggle-content");
        const otherIcon = otherItem.querySelector(".faq-item-icon");

        if (!otherContent || !otherIcon) return;

        gsap.killTweensOf([otherContent, otherIcon]);

        if (otherItem !== item) {
          otherItem.classList.remove(activeClass);

          gsap.to(otherContent, {
            height: 0,
            duration: 0.3,
            ease: "power2.inOut"
          });

          gsap.to(otherIcon, {
            rotation: 0,
            duration: 0.3,
            ease: "power2.inOut"
          });
        }
      });

      gsap.killTweensOf([content, icon]);

      if (isActive) {
        item.classList.remove(activeClass);

        gsap.to(content, {
          height: 0,
          duration: 0.3,
          ease: "power2.inOut"
        });

        gsap.to(icon, {
          rotation: 0,
          duration: 0.3,
          ease: "power2.inOut"
        });
      } else {
        item.classList.add(activeClass);

        const targetHeight = content.scrollHeight;

        gsap.fromTo(
          content,
          { height: 0, overflow: "hidden" },
          {
            height: targetHeight,
            duration: 0.3,
            ease: "power2.inOut",
            onComplete: () => {
              gsap.set(content, { height: "auto" });
            }
          }
        );

        gsap.to(icon, {
          rotation: 135,
          duration: 0.3,
          ease: "power2.inOut"
        });
      }
    });
  });
});

