    }
  `;

  document.head.appendChild(style);

  function createTrainCounter(counter) {

    const originalText = counter.textContent.trim();

    counter.innerHTML = "";

    let digitPosition = 0;

    const trains = [];

    [...originalText].forEach((char) => {

      if (/^\d$/.test(char)) {

        const targetDigit = Number(char);

        const digitWindow =
          document.createElement("span");

        digitWindow.className =
          "digit-window";

        const digitTrain =
          document.createElement("span");

        digitTrain.className =
          "digit-train";

        for (let cycle = 0; cycle < 4; cycle++) {

          for (let number = 0; number <= 9; number++) {

            const digit =
              document.createElement("span");

            digit.className = "digit";

            digit.textContent = number;

            digitTrain.appendChild(digit);

          }

        }

        digitWindow.appendChild(digitTrain);

        counter.appendChild(digitWindow);

        const direction =
          digitPosition % 2 === 0
            ? "up"
            : "down";


        trains.push({
          train: digitTrain,
          window: digitWindow,
          targetDigit,
          direction
        });


        digitPosition++;

      }

      else {

        const staticChar =
          document.createElement("span");

        staticChar.className =
          "static-char";


        if (char === ".") {
          staticChar.classList.add("dot");
        }


        staticChar.textContent = char;

        counter.appendChild(staticChar);

      }

    });

    requestAnimationFrame(() => {

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: counter,
          start: "top 80%",
          once: true
        }
      });

      trains.forEach((item) => {

        const digitHeight =
          item.window.offsetHeight;

        const finalIndex =
          item.targetDigit + 20;

        if (item.direction === "up") {

          const startIndex =
            item.targetDigit + 10;


          gsap.set(item.train, {
            y: -(startIndex * digitHeight)
          });


          tl.to(
            item.train,
            {
              y: -(finalIndex * digitHeight),
              duration: 2.5,
              ease: "power3.out"
            },
            0
          );

