          const startIndex =
            item.targetDigit + 30;


          gsap.set(item.train, {
            y: -(startIndex * digitHeight)
          });


          tl.to(
            item.train,
            {
              y: -(finalIndex * digitHeight),
              duration: 2.5,
              ease: "power3.out"
            },
            0
          );

        }

      });

      ScrollTrigger.refresh();

    });

  }

  document
    .querySelectorAll(".train-counter")
    .forEach(createTrainCounter);


});

